"""Review structural landmarks, newly generated boundaries, and the frozen ranker."""
import argparse
import json
from pathlib import Path

import hah_shape_trial_report as original


def build(folder):
    original.build(folder)
    html=original.HTML
    html=html.replace('Medial ح · shape trial','Medial ح · structural cuts')
    html=html.replace('Compare the whole letter shape and its two boundaries. The same body family covers ح، ج، خ.',
                      'New cut positions come from the open mouth, upper lip, returning stroke, and attachment branches. The same body family covers ح، ج، خ.')
    html=html.replace('<div class="grid">','<section class="card" style="margin-bottom:14px"><h2>Detected structure · before placing cuts</h2><div id="structure" class="figure" style="height:240px"></div><p id="structureCaption" class="caption"></p></section><div class="grid">',1)
    html=html.replace('Shape-ranked candidate','Generated structural cuts')
    html=html.replace('Route anchor','Lip landmark')
    html=html.replace('Intrinsic measurements and generating routes','Intrinsic features and cut parameters')
    old='It proposes two cuts around a possible medial hah using six existing contour routes, broadens the anchor search, then ranks the resulting bodies by contour similarity, stroke-relative proportions, concavity, counters, and boundary placement within the body. All candidate cuts come from the source contour. Other letters do not supply endpoint landmarks.'
    new='It builds a stroke graph from the raw ink and locates a left-opening mouth between an upper lip and a returning stroke. It checks the opening against actual white space. Attachments may occur along the lip in stacked forms. A rising or descending attaching stroke stays with hah until its first turn into the rightward join. That turn, junction geometry, and nearby contour corners propose normals; each normal is intersected with the original SVG curves to make exact vector cuts. The existing direction-walk routes are not called. The earlier shape scorer is reused unchanged to rank the new candidates.'
    assert old in html;html=html.replace(old,new)
    html=html.replace('An unrepresented shape or a cut not generated by a route can still be missed.',
                      'This first structural generator targets open-head forms. Closed, fused, or incorrectly detected structures can remain unresolved. A detected structure and an acceptable cut are separate checks.')
    html=html.replace('Only the one reviewed mask on page 590 is an independent human comparison.',
                      'The one reviewed mask on page 590 is a human reference. Pages 590 and 600 were previously inspected during earlier work, so this is a regression comparison, not a pristine unseen end-to-end test.')
    insert=r'''
function structureDrawing(c){const f=c?.structuralFeatures||word.structuralDetections?.[0];if(!f){$('structure').innerHTML=svg(word.ink,null);$('structureCaption').textContent='No supported open-head structure detected.';return}
 let extra='';for(const [name,color] of [['lipBranch','#286bb1'],['returnBranch','#a14e9a'],[f.attachmentStroke?'attachmentStroke':'entryBranch','#c18219']])extra+=`<polyline points="${f[name].map(p=>p.join(',')).join(' ')}" fill="none" stroke="${color}" stroke-width=".10"/>`;
 const labels=[['lipTip','lip','#286bb1',-1,-.8],['root','mouth root','#a14e9a',-1.1,-1.1],['attachment','attachment start','#c18219',.4,-.8],['returnOutlet','return outlet','#a14e9a',-1.1,1.2]];if(f.attachmentStrokeEnd)labels.push(['attachmentStrokeEnd','joining turn','#c18219',.7,1.2]);
 for(const [key,label,color,dx,dy] of labels){const p=f[key],q=[p[0]+dx*f.stroke,p[1]+dy*f.stroke];extra+=`<circle cx="${p[0]}" cy="${p[1]}" r=".10" fill="${color}"/>${line(p,q,color)}<text x="${q[0]}" y="${q[1]}" font-size=".40" fill="${color}">${label}</text>`}
 for(const s of f.mouthSamples)extra+=`<circle cx="${s.air[0]}" cy="${s.air[1]}" r=".11" fill="#12a78d"/>`;
 const points=[f.lipTip,f.root,f.crest,f.attachment,f.returnOutlet,...(f.attachmentStrokeEnd?[f.attachmentStrokeEnd]:[])],xs=points.map(p=>p[0]),ys=points.map(p=>p[1]),padding=2*f.stroke;const box=[Math.min(...xs)-padding,Math.min(...ys)-padding,Math.max(...xs)-Math.min(...xs)+2*padding,Math.max(...ys)-Math.min(...ys)+2*padding];
 $('structure').innerHTML=svg(word.ink,null,extra,box);$('structureCaption').textContent=`Blue: upper lip. Purple: returning stroke. Gold: ${f.attachmentStroke?'attaching stroke included in hah, through its joining turn':'attachment branch'}. Green points verify the opening is white space. Local stroke ${f.stroke.toFixed(3)} native units. ${c?'Entry: '+c.structuralParameters.entryOffset+(f.attachmentStroke?' beyond the joining turn':' from attachment')+'; outlet: '+c.structuralParameters.outletOffset+' (stroke units, or detected corner).':''}`;
}
'''
    html=html.replace('function render(){',insert+'\nfunction render(){')
    html=html.replace("$('wordTitle').textContent=`${word.id}","structureDrawing(candidate); $('wordTitle').textContent=`${word.id}")
    html=html.replace("r.originalAnchorChecks?'original anchor checks':'expanded anchor search'","r.generator==='intrinsic-structure'?'structural landmarks':(r.originalAnchorChecks?'original anchor checks':'expanded anchor search')")
    html=html.replace("['baseline','trial','difference','baselineCaption'","['structure','structureCaption','baseline','trial','difference','baselineCaption'")
    html=html.replace('One mask is insufficient to establish general accuracy. Open alternatives to distinguish candidate-generation failures from ranking failures.',
                      'Best generated candidate: ${pct(h.oracleIoU)} (evaluation only). Previous route candidates reached ${pct(h.oldCandidateOracleIoU)}. ${h.previousStructuralIoU!=null?"Before including the attaching stroke: "+pct(h.previousStructuralIoU)+".":""} The automatic choice and the best available candidate are separate results.')
    (folder/'review/index.html').write_text(html)


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__);parser.add_argument('--folder',type=Path,required=True)
    build(parser.parse_args().folder)
